/**
 * Cờ Gánh — daily puzzle bank (machine-generated + machine-verified).
 *
 * Generated by scripts/gen-puzzles.ts: random self-play positions where
 * the side to move wins IMMEDIATELY — either by flipping every enemy
 * piece ("flipall") or by leaving the opponent with no legal move
 * ("nomoves"). The view re-verifies the user's move with the engine at
 * runtime, so ANY winning move is accepted; `solution` records one.
 */

export interface CgPuzzle {
  id: string;
  /** 25-char board string ('B' blue, 'R' red, '.' empty). */
  pos: string;
  turn: "blue" | "red";
  /** One winning move (engine label). */
  solution: string;
  flips: number;
  kind: "flipall" | "nomoves";
}

