/** Day key in the user's local timezone (YYYY-MM-DD). */
export function puzzleDayKey(d = new Date()): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

/** The puzzle for a given date (deterministic rotation). */
export function dailyPuzzle(d = new Date()): CgPuzzle {
  const start = Date.UTC(d.getFullYear(), 0, 0);
  const dayOfYear = Math.floor((Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) - start) / 86400000);
  return PUZZLES[dayOfYear % PUZZLES.length];
}

const SOLVED_KEY = "cg-puzzle-solved";

export function loadSolvedDays(): Record<string, string> {
  try {
    return JSON.parse(localStorage.getItem(SOLVED_KEY) || "{}") as Record<string, string>;
  } catch {
    return {};
  }
}

export function markSolved(dayKey: string, puzzleId: string): void {
  try {
    const all = loadSolvedDays();
    all[dayKey] = puzzleId;
    localStorage.setItem(SOLVED_KEY, JSON.stringify(all));
  } catch { /* private mode */ }
}

/** Current streak: consecutive solved days ending today or yesterday. */
export function puzzleStreak(d = new Date()): number {
  const solved = loadSolvedDays();
  let streak = 0;
  const cursor = new Date(d);
  if (!solved[puzzleDayKey(cursor)]) cursor.setDate(cursor.getDate() - 1);
  while (solved[puzzleDayKey(cursor)]) {
    streak++;
    cursor.setDate(cursor.getDate() - 1);
  }
  return streak;
}
